INSERT INTO `paso` VALUES (31,'no me los revuelvas',1,18,'no me revuelvas los Ã±oquis'),(32,'1',1,19,'messi'),(33,'siuuu',2,19,'el bicho'),(40,'Agarras un vaso vacÃ­o y que estÃ© limpio en lo posible, si no tenes uno vas a comprarlo. Si no estÃ¡ vacÃ­o tampoco sirve.',1,22,'Agarras un vaso'),(41,'Pones muchos hielitos que estÃ©n bien frios.',2,22,'Pones hielitos'),(42,'Vertis la fanta loka en el vaso. Ojo que tiene que estar muy loca.',3,22,'Pones la fanta loca'),(43,'Agregar el vodka y el curaÃ§ao, batir por medio minuto mÃ¡s.',1,24,'Agregar el vodka y el curaÃ§ao'),(44,'AÃ±adir hielo y batir por 1 minuto mÃ¡s.\n',2,24,'AÃ±adir hielo'),(45,'Decorar con rodaja de limÃ³n.',3,24,'Decorar '),(50,'1',1,27,'1'),(51,'1',1,28,'1'),(52,'1',1,26,'1'),(53,'1',1,29,'1'),(54,'LlenÃ© un vaso con bastante hielo (unos 100 g).\n',1,30,'Paso 1: Poner el hielo'),(55,'Le puse 80 ml de Cinzano.\n',2,30,'Paso 2: Agregar el Cinzano'),(56,'CompletÃ© con agua tÃ³nica bien frÃ­a (aprox. 300 ml, pero a gusto).\n',3,30,'Paso 3: Completar con Tonica'),(57,'Unas vueltas suaves para mezclar y listo.\n',4,30,'Paso 4: Mezclar'),(58,'Dejamos el vaso un buen rato en el congelador',1,31,'Paso 1: Enfriar el Vaso'),(59,'LlenÃ¡ el vaso con hielo en cubos hasta el tope.\n',2,31,'Paso 2: Hielos'),(60,'Servir el Fernet hasta la cantidad que quieras, yo prefiero un 30% (aprox 90ml).\n',3,31,'Paso 3: Fernet'),(61,'Completamos el trago con gaseosa sabor cola.',4,31,'Paso 4: Gaseosa'),(62,'Poner la menta y el azÃºcar en un copÃ³n o vaso de trago largo. Machacar apenas la menta.',1,32,'Paso 1: '),(63,'Agregar el hielo preferentemente molido y el Cynar.',2,32,'Paso 2:'),(64,'Completar con jugo de naranja (si es exprimido mejor, pero estas opciones que viene con pulpa no estÃ¡n nada mal).',3,32,'Paso 3: '),(65,'Servir y disfrutar',4,32,'Paso 4:'),(89,'Lava bien las frutillas y quita el tallo. Si usas frutillas frescas, cÃ³rtalas en trozos pequeÃ±os para facilitar el licuado. Si usas congeladas, no es necesario cortarlas.',1,49,'PreparaciÃ³n de las Frutillas'),(90,'En el vaso de la licuadora, vierte el ron blanco, el jugo de limÃ³n (o lima) reciÃ©n exprimido y el almÃ­bar simple. AsegÃºrate de usar las medidas exactas (60 ml, 30 ml y 15 ml).',2,49,'Medir los LÃ­quidos'),(91,'Incorpora las frutillas (100 gr) y una taza de hielo. La cantidad de hielo es crucial para obtener la textura \"frozen\" caracterÃ­stica del daiquirÃ­.',3,49,'AÃ±adir las Frutas y Hielo'),(92,'LicÃºa a mÃ¡xima potencia. Comienza con pulsaciones cortas y luego mantÃ©n hasta que la mezcla sea completamente homogÃ©nea y adquiera la textura de sorbete o granizado. Si es muy espeso, agrega un toque extra de ron o jugo de limÃ³n.',4,49,'Licuado y Texturizado'),(93,'Vierte el contenido en una copa de cÃ³ctel o copa de flauta. Decora el borde del vaso con media frutilla o un trozo de cÃ¡scara de limÃ³n. Â¡Sirve inmediatamente!',5,49,'Servicio y DecoraciÃ³n'),(94,'En un vaso tipo Long drink (o de trago largo), coloca las 2 cucharadas de azÃºcar. AÃ±ade las hojas de menta o hierbabuena. Con un mortero o mazo de madera, presiona suavemente la menta solo para liberar sus aceites, sin triturar ni romper las hojas.',1,50,'Macerar la Menta y el AzÃºcar'),(95,'Vierte el jugo de limÃ³n fresco (30 ml) y remueve bien para disolver el azÃºcar en el fondo del vaso. Agrega el ron blanco (60 ml).',2,50,'Integrar el CÃ­trico y el Ron'),(96,'Llena el vaso completamente con hielo en cubos. El Mojito debe ser un trago muy frÃ­o.',3,50,'AÃ±adir el Hielo'),(97,'Rellena el vaso con agua con gas, soda o tÃ³nica (aproximadamente 120 ml). Usa una cuchara de bar de mango largo para remover la mezcla con movimientos suaves de abajo hacia arriba.',4,50,'Completar y Remover'),(98,'Decora con una rama de menta fresca en la parte superior, golpeada ligeramente contra la mano para liberar su aroma. Opcionalmente, aÃ±ade una rodaja de limÃ³n. Â¡Sirve con pajita!',5,50,'DecoraciÃ³n Final'),(99,'EnfrÃ­a una copa de balÃ³n, una copa de cÃ³ctel o un vaso alto. Puedes llenarla con hielo y agua, y descartar el contenido justo antes de servir.',1,51,'Enfriar la CristalerÃ­a'),(100,'En una coctelera llena de hielo, combina el jugo de naranja (60 ml), el jugo de durazno (60 ml), el jugo de limÃ³n fresco (30 ml) y el almÃ­bar (15 ml, si lo usas para compensar el dulzor de los jugos).',2,51,'Mezclar la Base de Jugos'),(101,'Tapa firmemente la coctelera y agita vigorosamente durante unos 10 a 15 segundos. El objetivo es enfriar bien y airear la mezcla. Filtra la mezcla directamente sobre la copa frÃ­a.',3,51,'Agitar y Filtrar'),(102,'Este paso es crucial para el color. Vierte la granadina (15 ml) lentamente sobre la superficie de la bebida. Para lograr un mejor efecto visual de capa, viÃ©rtela deslizÃ¡ndola suavemente por la pared interior del vaso.',4,51,'AÃ±adir la Granadina (Efecto Capa)'),(103,'Decora de forma colorida y vistosa, utilizando una rodaja de naranja, una cereza al marrasquino y una guinda, o una rodaja de limÃ³n. Sirve con una pajita larga y Â¡a disfrutar de esta explosiÃ³n de color!',5,51,'Decorar y Servir'),(104,'Cortamos el pomelo al medio, y lo exprimimos para sacarle el jugo.',1,52,'Pomelo'),(105,'Agregamos hielo en un vaso largo',2,52,'Hielo'),(106,'Agregamos algun tipo de endulzante al trago para que este no este tan amargo. Yo use azucar.',3,52,'Endulzante'),(107,'Agregamos un par de medidas de whisky al vaso. Luego bati y disfruta!',4,52,'Whisky'),(108,'Ponemos los duraznos junto con el almÃ­bar en la licuadora, aÃ±adimos el agua y licuamos. Si la lata de duraznos estÃ¡ frÃ­a mejor.',1,53,'AÃ±adir ingredientes'),(109,'AÃ±adimos azÃºcar, hielo y whisky y volvemos a licuar. Los cubos de hielo los vamos agregando de a poco.',2,53,'Licuar'),(110,'Y listo! Servir con algunos cubitos de hielo. Sale mÃ¡s o menos 1 litro y medio.',3,53,'Servir y decorar'),(111,'Para que esta receta os quede perfecta, el paso nÂ°1 tiene que ser exprimir 4 o 5 granadas para tener preparado el zumo natural. Y ojo porque aunque la famosa \"granadina\" tenga un color similar, no es para nada lo mismo.',1,54,''),(112,'Para preparar el gintonic, exprimimos 1/2 limÃ³n dentro del vaso. DespuÃ©s aÃ±adimos la ginebra y un puÃ±ado de hielo y removemos. AÃ±adimos la tÃ³nica. Y en este momento aÃ±adimos el zumo de granada. La cantidad dependerÃ¡ de lo rosa que querÃ¡is que os quede, yo creo que echÃ© 1 cucharada o un pelÃ­n mÃ¡sðŸ˜Š Si vais a preparar este gintonic para invitados, este paso dejadlo para la mesa, porque queda genialðŸ¤© Acabamos de rellenar el vaso de hielo...',2,54,''),(113,'removemos un poco, y ya lo tenemos listo! A disfrutar de un gintonic tradicional con un toque de granada que le va de maravillaðŸ‘ŒðŸ½ Para decorar hemos hecho una brocheta de frambuesas y rodajitas de limÃ³n!ðŸ‹',3,54,''),(114,'Si tenes un vaso de aluminio como el de la foto, enfrialo un buen rato antes en el frezer (recomiendo 1 horita)',1,55,'Enfriar el vaso'),(115,'Llena el vaso con una buena cantidad de hielos, mejor que sobre y que no falte!',2,55,'Hielos'),(116,'Agrega vino al vaso, hasta completar aproximadamente un 30% del vaso',3,55,'Vino'),(117,'Completa el trago con gaseosa de pomelo, y disfruta!',4,55,'Gaseosa de Pomelo'),(118,'Agregas un par de hielos en un vaso como el de la foto',1,56,'Hielos'),(119,'Agregas una medida de gancia (a placer)',2,56,'Gancia'),(120,'Completas con pomelo',3,56,'Pomelo'),(121,'Para darle el twist final a este trago, le agregas un par de hojas de menta',4,56,'Menta'),(122,'Agrega hielo en un vaso largo como el de la foto',1,57,'Hielo'),(123,'Llena el 50% del vaso con amargo obrero',2,57,'Amargo Obrero'),(124,'Completa con pomelo rosado, un 50% aproximadamente',3,57,'Pomelo'),(125,'Podes decorar como yo tu vaso con una rodaja de pomelo rosado',4,57,'Opcional'),(126,'Vierte el zumo de pomelo y el Aperol en una copa coupe enfriada. ',1,58,''),(127,'AÃ±ade hielo y revuelve suavemente para combinar. ',2,58,''),(128,'Completa con el prosecco',3,58,''),(129,'Decorar con una cÃ¡scara de pomelo y sirve inmediatamente.',4,58,''),(130,'',1,59,' Lavar el pomelo y exprimirlo. Reservar.'),(131,'Agregar el jugo de pomelo exprimido. Revolver y a disfrutar! Yo tenÃ­a whisky Johnie Walker, pero pueden usar el de la marca que tengan. A disfrutar ðŸ˜‹ðŸ¥ƒ',2,59,'En un vaso'),(147,'Corta las maracuyÃ¡s por la mitad y extrae la pulpa con una cuchara. Cuela el contenido para separar el jugo de las semillas, reservando algunas semillas para la decoraciÃ³n final.',1,67,''),(148,'Si tienes coctelera, Ã¡brela y aÃ±ade 3-4 cubos de hielo junto con todos los ingredientes lÃ­quidos. Las medidas estÃ¡n calculadas basÃ¡ndonos en chupitos estÃ¡ndar de 30 mililitros cada uno.',2,67,''),(149,'Cierra la coctelera hermÃ©ticamente y agita de forma enÃ©rgica durante 15-20 segundos. Este paso es crucial para que se enfrÃ­e completamente y se integren todos los sabores de este cÃ³ctel de maracuyÃ¡ con ron.',3,67,''),(150,'Prepara un vaso corto tipo whisky con hielos frescos. VacÃ­a el contenido de la coctelera usando un colador para obtener una textura suave y sin trozos de hielo.',4,67,''),(151,'AÃ±ade unas gotas de amargos de angostura sobre la superficie, esparce algunas semillas de maracuyÃ¡ fresco y corona con hojas de menta para un aroma irresistible. Sirve inmediatamente despuÃ©s de preparar para mantener la temperatura frÃ­a y la efervescencia natural de los ingredientes mezclados. Â¡Y ya estÃ¡! CuÃ©ntanos en los comentarios cÃ³mo te quedÃ³ y no olvides subir una fotografÃ­a tu plato. Â¡Nos encantarÃ¡ ver el resultado!',5,67,''),(152,'En un vaso, machacar el azÃºcar, las frutillas, el limÃ³n cortado en lÃ¡minas finas y las hojas de menta fresca apretando, machacando con algÃºn utensillo para suelten bien sus jugos y aroma.',1,68,''),(153,'AÃ±adir buena cantidad de hielo encima y el ron (o alguna de las otras bebidas), y el refresco de limÃ³n con gas puede ser soda tambiÃ©n.',2,68,''),(154,'Disfrutar!!!',3,68,''),(155,'Elegir un vaso alto de vidrio y lle