DROP TABLE IF EXISTS `voto`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `voto` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fecha_de_voto` datetime DEFAULT NULL,
  `valor` float DEFAULT NULL,
  `receta_id` int NOT NULL,
  `usuario_id` int NOT NULL,
  `tipo` enum('Like','Dislike','Favorito','ComentarioLike') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `comentario_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `receta_id` (`receta_id`),
  KEY `usuario_id` (`usuario_id`),
  KEY `voto_comentario_FK` (`comentario_id`),
  CONSTRAINT `voto_comentario_FK` FOREIGN KEY (`comentario_id`) REFERENCES `comentario` (`id`),
  CONSTRAINT `voto_ibfk_1` FOREIGN KEY (`receta_id`) REFERENCES `receta` (`id`) ON DELETE CASCADE,
